#!/bin/bash
# SecureXL rate limiting profile 'Monitor' for A-DMZ (192.168.12.101)
# Generated by the SecureXL Rate Limiting portal.
#
# Run in Expert mode on EACH cluster member:  bash admz-monitor.sh
# Pass --dry-run to print the commands without running them.
# Removes existing rules named 'ADMZ-*' first, and only those.

PREFIX='ADMZ-'
DRY=0; [ "$1" = "--dry-run" ] && DRY=1

run() {
    echo "+ $*"
    [ $DRY -eq 1 ] && return 0
    "$@" || echo "  !! failed (exit $?) - check the syntax for this build with: fwaccel dos rate -h"
}

echo "== Removing previous lab rules ($PREFIX*) =="
fwaccel dos rate get | awk -v p="$PREFIX" '
  /uid=/ && index($0, "name=" p) { if (match($0, /uid=(<[^>]*>|[^ ]+)/)) print substr($0, RSTART + 4, RLENGTH - 4); next }
  /^[ \t]*Rule UID[ \t]/ { uid = $NF; next }
  /^[ \t]*(Rule )?Name[ \t]/ && index($NF, p) == 1 && uid != "" { print uid; uid = "" }' |
while read -r uid; do run fwaccel dos rate del "$uid"; done

echo "== Installing profile 'Monitor' =="
run fwaccel dos rate add -a n -n ADMZ-MON-pkt-src destination cidr:192.168.12.101/32 pkt-rate 2000 track source
run fwaccel dos rate add -a n -n ADMZ-MON-http-conn destination cidr:192.168.12.101/32 service 6/80 new-conn-rate 25 track source
run fwaccel dos rate add -a n -n ADMZ-MON-https-conn destination cidr:192.168.12.101/32 service 6/443 new-conn-rate 25 track source
run fwaccel dos rate add -a n -n ADMZ-MON-ssh-conn destination cidr:192.168.12.101/32 service 6/22 new-conn-rate 3 track source
run fwaccel dos rate add -a n -n ADMZ-MON-aggregate destination cidr:192.168.12.101/32 pkt-rate 20000
run fwaccel dos pbox --set-drops-threshold 500
run fwaccel dos pbox --set-timeout 180
run fwaccel dos pbox --set-log-drops on
run fwaccel dos pbox --set-enabled off

echo "== Result =="
fwaccel dos rate get
fwaccel dos pbox --show-config
